109	static lv_obj_t *launcher_label(lv_obj_t *parent, const char *text,
110	                                const lv_font_t *font, uint32_t color,
111	                                lv_align_t align, int32_t x, int32_t y)
112	{
113	  lv_obj_t *label = lv_label_create(parent);
114	
115	  lv_obj_set_style_text_font(label, font, 0);
116	  lv_obj_set_style_text_color(label, lv_color_hex(color), 0);
117	  lv_label_set_text(label, text);
118	  lv_obj_align(label, align, x, y);
119	  return label;
120	}
