272	/* Position and size are in grid cells */
273	
274	static void launcher_place(lv_obj_t *tile, int col, int row, int w, int h)
275	{
276	  lv_obj_set_pos(tile, col * LAUNCHER_TILE_STEP, row * LAUNCHER_TILE_STEP);
277	  lv_obj_set_size(tile, w * LAUNCHER_TILE_STEP - LAUNCHER_TILE_GAP,
278	                  h * LAUNCHER_TILE_STEP - LAUNCHER_TILE_GAP);
279	}
