655	/****************************************************************************
656	 * Name: lifecycle
657	 ****************************************************************************/
658	
659	static void launcher_periodic_cb(lv_timer_t *timer)
660	{
661	  struct mallinfo mi = mallinfo();
662	  struct timespec ts;
663	  unsigned int sec;
664	
665	  UNUSED(timer);
666	
667	  clock_gettime(CLOCK_MONOTONIC, &ts);
668	  sec = ts.tv_sec;
669	
670	  lv_label_set_text_fmt(g_lock_clock, "%02u:%02u:%02u",
671	                        (sec / 3600) % 100, (sec / 60) % 60, sec % 60);
672	  lv_label_set_text(g_home_clock, lv_label_get_text(g_lock_clock));
673	  lv_label_set_text_fmt(g_home_heap, "%u KB", mi.fordblks / 1024);
674	  lv_label_set_text_fmt(g_about_uptime, "%u s", sec);
675	  lv_label_set_text_fmt(g_about_heap, "%u KB", mi.fordblks / 1024);
676	}
677	
678	/* "last" is the app that just exited, or -1 on boot */
679	
680	static int launcher_start(int last)
681	{
682	  lv_nuttx_dsc_t info;
683	  lv_obj_t *obj;
684	
685	  lv_init();
686	
687	  lv_nuttx_dsc_init(&info);
688	  lv_nuttx_init(&info, &g_result);
689	
690	  if (g_result.disp == NULL || g_result.indev == NULL)
691	    {
692	      fprintf(stderr, "launcher: no display or touchscreen\n");
693	      return -ENODEV;
694	    }
695	
696	  lv_style_transition_dsc_init(&g_press_trans, g_press_props,
697	                               lv_anim_path_ease_out, 120, 0, NULL);
698	
699	  launcher_create_about_scr();
700	  launcher_create_home_scr(last);
701	  launcher_create_lock();
702	  lv_screen_load(g_home_scr);
703	
704	  launcher_periodic_cb(NULL);
705	  lv_timer_create(launcher_periodic_cb, 1000, NULL);
706	  lv_timer_create(launcher_flip_cb, LAUNCHER_FLIP_PERIOD, NULL);
707	
708	  if (last < 0)
709	    {
710	      lv_obj_add_flag(g_home_tiles, LV_OBJ_FLAG_HIDDEN);
711	      return 0;
712	    }
713	
714	  /* Shrink the app back into its tile */
715	
716	  lv_obj_add_flag(g_lock, LV_OBJ_FLAG_HIDDEN);
717	  lv_obj_update_layout(g_home_scr);
718	  lv_obj_get_coords(g_return_tile, &g_zoom_area);
719	
720	  obj = launcher_app_tile(lv_layer_top(), last, false);
721	  launcher_anim(obj, launcher_zoom_cb, LAUNCHER_ZOOM_MAX, 0, 0,
722	                lv_anim_path_ease_in_out, lv_obj_delete_anim_completed_cb);
723	  return 0;
724	}
725	
726	static void launcher_stop(void)
727	{
728	  lv_nuttx_deinit(&g_result);
729	  lv_deinit();
730	}
731	
732	/****************************************************************************
733	 * Public Functions
734	 ****************************************************************************/
735	
736	int main(int argc, FAR char *argv[])
737	{
738	  FAR const struct builtin_s *app;
739	  uint32_t idle;
740	  int last = -1;
741	  pid_t pid;
742	
743	  UNUSED(argc);
744	  UNUSED(argv);
745	
746	  if (lv_is_initialized())
747	    {
748	      fprintf(stderr, "launcher: LVGL is busy\n");
749	      return 1;
750	    }
751	
752	  while (launcher_start(last) == 0)
753	    {
754	      g_launch = -1;
755	      while (g_launch < 0)
756	        {
757	          idle = lv_timer_handler();
758	          usleep(MAX(idle, 1) * 1000);
759	        }
760	
761	      /* Keep the zoomed tile on screen while the app starts */
762	
763	      lv_refr_now(NULL);
764	      launcher_stop();
765	
766	      last = g_launch;
767	      app = builtin_for_index(last);
768	      pid = task_create(app->name, app->priority, app->stacksize, app->main,
769	                        NULL);
770	      if (pid < 0)
771	        {
772	          fprintf(stderr, "launcher: start %s failed: %d\n", app->name,
773	                  errno);
774	        }
775	      else
776	        {
777	          waitpid(pid, NULL, 0);
778	        }
779	    }
780	
781	  launcher_stop();
782	  return 1;
783	}
