71	
72	static const struct bench_test_s g_tests[] =
73	{
74	  { "Integer (xorshift)", bench_int, 6 * BENCH_INT_LOOPS, "MOPS" },
75	  { "Float (matmul)", bench_float,
76	    2 * BENCH_MATRIX_N * BENCH_MATRIX_N * BENCH_MATRIX_N, "MFLOPS" },
77	  { "Memory copy", bench_memcpy, BENCH_MEM_SIZE, "MB/s" },
