200	/* Redraw the whole screen BENCH_FRAMES times through a top layer rect */
201	
202	static void bench_refresh(lv_obj_t *label, lv_opa_t opa)
203	{
204	  lv_obj_t *obj = bench_rect(lv_layer_top(), 0, 0, BENCH_SCREEN_W,
205	                             BENCH_SCREEN_H);
206	  uint32_t start = bench_ms();
207	  uint32_t elapsed;
208	  int i;
209	
210	  lv_obj_set_style_bg_opa(obj, opa, 0);
211	
212	  for (i = 0; i < BENCH_FRAMES; i++)
213	    {
214	      lv_obj_set_style_bg_color(obj,
215	        lv_color_hsv_to_rgb(i * 360 / BENCH_FRAMES, 70, 90), 0);
216	      lv_refr_now(NULL);
217	    }
218	
219	  elapsed = bench_ms() - start;
220	  lv_obj_delete(obj);
221	
222	  lv_label_set_text_fmt(label, "%u fps, %u Mpx/s",
223	                        BENCH_FRAMES * 1000 / elapsed,
224	                        (uint32_t)((uint64_t)BENCH_FRAMES * BENCH_SCREEN_W *
225	                                   BENCH_SCREEN_H / elapsed / 1000));
226	}
