228	static void bench_pattern_show(lv_obj_t *overlay)
229	{
230	  static const uint32_t ramps[] =
231	  {
232	    0xff0000, 0x00ff00, 0x0000ff, 0xffffff
233	  };
234	
235	  lv_obj_t *obj;
236	  int i;
237	
238	  lv_obj_clean(overlay);
239	  lv_obj_set_style_bg_color(overlay, lv_color_black(), 0);
240	
241	  if (g_pattern < nitems(g_pattern_colors))
242	    {
243	      /* Solid colors to spot dead or stuck pixels */
244	
245	      lv_obj_set_style_bg_color(overlay,
246	                                lv_color_hex(g_pattern_colors[g_pattern]),
247	                                0);
248	    }
249	  else if (g_pattern == nitems(g_pattern_colors))
250	    {
251	      /* Black to full intensity ramps to check color depth and banding */
252	
253	      for (i = 0; i < nitems(ramps); i++)
254	        {
255	          obj = bench_rect(overlay, 0, i * BENCH_SCREEN_H / nitems(ramps),
256	                           BENCH_SCREEN_W, BENCH_SCREEN_H / nitems(ramps));
257	          lv_obj_set_style_bg_color(obj, lv_color_black(), 0);
258	          lv_obj_set_style_bg_grad_color(obj, lv_color_hex(ramps[i]), 0);
259	          lv_obj_set_style_bg_grad_dir(obj, LV_GRAD_DIR_HOR, 0);
260	        }
261	    }
262	  else
263	    {
264	      /* 1px grid, including the outermost rows and columns */
265	
266	      for (i = 0; i <= BENCH_SCREEN_W; i += BENCH_GRID_STEP)
267	        {
268	          bench_rect(overlay, MIN(i, BENCH_SCREEN_W - 1), 0, 1,
269	                     BENCH_SCREEN_H);
270	        }
271	
272	      for (i = 0; i <= BENCH_SCREEN_H; i += BENCH_GRID_STEP)
273	        {
274	          bench_rect(overlay, 0, MIN(i, BENCH_SCREEN_H - 1),
275	                     BENCH_SCREEN_W, 1);
276	        }
277	    }
278	}
