255	/****************************************************************************
256	 * Public Functions
257	 ****************************************************************************/
258	
259	int main(int argc, FAR char *argv[])
260	{
261	  lv_nuttx_dsc_t info;
262	  lv_nuttx_result_t result;
263	  uint32_t idle;
264	
265	  UNUSED(argc);
266	  UNUSED(argv);
267	
268	  /* LVGL is one global instance, shared by every task of the flat build */
269	
270	  if (lv_is_initialized())
271	    {
272	      fprintf(stderr, "paint: LVGL is busy, start it from the launcher\n");
273	      return 1;
274	    }
275	
276	  g_canvas_buf = memalign(64, PAINT_BUF_SIZE);
277	  if (g_canvas_buf == NULL)
278	    {
279	      fprintf(stderr, "paint: canvas alloc failed\n");
280	      return 1;
281	    }
282	
283	  lv_init();
284	
285	  lv_nuttx_dsc_init(&info);
286	  lv_nuttx_init(&info, &result);
287	
288	  if (result.disp == NULL || result.indev == NULL)
289	    {
290	      fprintf(stderr, "paint: no display or touchscreen\n");
291	      g_running = false;
292	    }
293	  else
294	    {
295	      paint_create();
296	      g_running = true;
297	    }
298	
299	  while (g_running)
300	    {
301	      idle = lv_timer_handler();
302	      usleep(MAX(idle, 1) * 1000);
303	    }
304	
305	  lv_nuttx_deinit(&result);
306	  lv_deinit();
307	  free(g_canvas_buf);
308	  return 0;
309	}
