static int s6_dsi_updatearea(FAR struct fb_vtable_s *vtable,
                             FAR const struct fb_area_s *area)
{
  FAR struct s6_dsi_fb_s *priv = (FAR struct s6_dsi_fb_s *)vtable;
  unsigned int endrow;
  size_t start;
  size_t len;

  DEBUGASSERT(vtable != NULL && area != NULL);

