    }

  start = area->y * S6_FB_STRIDE;
  len   = (endrow - area->y) * S6_FB_STRIDE;
  memcpy(priv->scanout + start, priv->fbmem + start, len);
  up_clean_dcache((uintptr_t)priv->scanout + start,
                  (uintptr_t)priv->scanout + start + len);
  return OK;
}

